        while (sc.hasNextInt()) {
            N = sc.nextInt(); T = sc.nextInt();
            if (N == 0 && T == 0) break;
            t = new int[N]; w = new int[N]; c = new int[N];
            for (int i = 0; i < N; i++) {
                t[i] = sc.nextInt(); w[i] = sc.nextInt(); c[i] = sc.nextInt();
            }
            int lo = 1, hi = N;
            while (lo < hi) {
                int mid = (lo + hi) / 2;
                if (canHandle(mid)) hi = mid;
                else lo = mid + 1;
            }
            System.out.println(lo);
        }
    }

    static boolean canHandle(int k) {
        // operators free times
        long[] ops = new long[k];
        // customer arrival times
        long[] arr = new long[N];
        boolean[] done = new boolean[N];
        int remaining = N;
        for (int iter = 0; iter < 10000 && remaining > 0; iter++) {
            // find next event time: min arrival of undone customers
            // assign operators greedily by earliest deadline
            // collect waiting customers at current time
            long minArr = Long.MAX_VALUE;
            for (int i = 0; i < N; i++) if (!done[i]) minArr = Math.min(minArr, arr[i]);
            if (minArr > T) return false;
            // get all customers arriving at minArr, sort by deadline
            // assign earliest free operators
            List<Integer> waiting = new ArrayList<>();
            for (int i = 0; i < N; i++) if (!done[i] && arr[i] == minArr) waiting.add(i);
            waiting.sort((a,b) -> Long.compare(arr[a]+w[a], arr[b]+w[b]));
            Arrays.sort(ops);
            for (int idx : waiting) {
                long deadline = arr[idx] + w[idx];
                long start = Math.max(ops[0], arr[idx]);
                if (start <= deadline && start + t[idx] <= T) {
                    ops[0] = start + t[idx];
                    Arrays.sort(ops);
                    done[idx] = true; remaining--;
                } else if (ops[0] > deadline) {
                    arr[idx] = deadline + c[idx];
                    if (arr[idx] > T) return false;
                }
            }
        }
        return remaining == 0;
    }
