/*
 * JAG support center
 *
 * We need the minimum number of operators so that, starting with all customers
 * calling at time 0, every customer finishes support within T.
 *
 * Customer i:
 *   s[i] : support time
 *   w[i] : maximum waiting time before hanging up
 *   r[i] : time until they call again after hanging up
 *
 * If a customer calls at time a, then that call must start by time a + w[i].
 * If not started, they hang up at a + w[i] and call again at a + w[i] + r[i].
 *
 * For a fixed number m of operators, feasibility can be checked greedily:
 *   - At any moment, among all currently waiting calls, if some call can be
 *     started, it is always optimal to start the one with earliest deadline
 *     (arrival + w).
 *   - When no call is waiting, jump to the next event time.
 *
 * However customers repeatedly call. For each customer, the k-th call arrives at
 *   a = k * (w[i] + r[i])
 * and has deadline
 *   d = a + w[i]
 * Only calls with arrival <= T matter; if a call arrives after T, it is irrelevant.
 *
 * We simulate event-driven with:
 *   - next arrival time for each customer
 *   - waiting queue ordered by deadline
 *   - running operators finishing at certain times
 *
 * At each step:
 *   1) add all arrivals up to current time
 *   2) finish all supports up to current time
 *   3) if some waiting call already missed deadline => infeasible
 *   4) assign available operators to earliest-deadline waiting calls
 *   5) advance time to next interesting event:
 *        min(next finish, next arrival, earliest waiting deadline if no free op)
 *
 * If all customers have been served at least once by time T, feasible.
 *
 * Then binary search m.
 *
 * Constraints are not provided here, so implementation is careful but simple.
 */
public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class WaitingCall {
        int id;
        long deadline;
        long arrival;
        WaitingCall(int id, long arrival, long deadline) {
            this.id = id;
            this.arrival = arrival;
            this.deadline = deadline;
        }
    }

    static class RunningJob {
        long finish;
        int id;
        RunningJob(long finish, int id) {
            this.finish = finish;
            this.id = id;
        }
    }

    static int n;
    static long T;
    static long[] s, w, r;

    static boolean feasible(int ops) {
        if (ops <= 0) return false;

        long[] nextArrival = new long[n];
        boolean[] served = new boolean[n];
        int servedCount = 0;

        PriorityQueue<WaitingCall> waiting = new PriorityQueue<>((a, b) -> {
            if (a.deadline != b.deadline) return Long.compare(a.deadline, b.deadline);
            return Integer.compare(a.id, b.id);
        });

        PriorityQueue<RunningJob> running = new PriorityQueue<>((a, b) -> Long.compare(a.finish, b.finish));

        long time = 0;
        int freeOps = ops;

        while (true) {
            // Add arrivals up to current time
            for (int i = 0; i < n; i++) {
                while (nextArrival[i] <= T && nextArrival[i] <= time && !served[i]) {
                    long a = nextArrival[i];
                    waiting.add(new WaitingCall(i, a, a + w[i]));
                    nextArrival[i] += w[i] + r[i];
                }
            }

            // Finish running jobs up to current time
            while (!running.isEmpty() && running.peek().finish <= time) {
                RunningJob job = running.poll();
                freeOps++;
                if (!served[job.id]) {
                    served[job.id] = true;
                    servedCount++;
                }
            }

            if (servedCount == n) return true;

            // Remove impossible state
            if (!waiting.isEmpty() && waiting.peek().deadline < time) return false;

            // Assign jobs greedily
            while (freeOps > 0 && !waiting.isEmpty()) {
                WaitingCall call = waiting.poll();
                if (call.deadline < time) return false;
                freeOps--;
                long finish = time + s[call.id];
                if (finish > T) return false; // must finish within T
                running.add(new RunningJob(finish, call.id));
            }

            if (servedCount == n) return true;

            long nextTime = Long.MAX_VALUE;

            // next finish
            if (!running.isEmpty()) nextTime = Math.min(nextTime, running.peek().finish);

            // next arrival of unserved customers
            for (int i = 0; i < n; i++) {
                if (!served[i] && nextArrival[i] <= T) {
                    nextTime = Math.min(nextTime, nextArrival[i]);
                }
            }

            // if no free operator, waiting deadlines also matter
            if (freeOps == 0 && !waiting.isEmpty()) {
                nextTime = Math.min(nextTime, waiting.peek().deadline);
            }

            // if there are waiting calls and free operators, we should have assigned them already
            // so if still waiting, freeOps==0.

            if (nextTime == Long.MAX_VALUE) break;
            if (nextTime == time) {
                // avoid infinite loop; if nothing changed and no assignment possible, impossible
                if (!running.isEmpty() && running.peek().finish == time) {
                    // loop will handle next iteration
                } else {
                    return false;
                }
            }
            time = nextTime;

            if (time > T) break;
        }

        return false;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        n = fs.nextInt();
        T = fs.nextLong();

        s = new long[n];
        w = new long[n];
        r = new long[n];

        for (int i = 0; i < n; i++) {
            s[i] = fs.nextLong();
            w[i] = fs.nextLong();
            r[i] = fs.nextLong();
        }

        int low = 1, high = n;
        while (low < high) {
            int mid = (low + high) >>> 1;
            if (feasible(mid)) high = mid;
            else low = mid + 1;
        }

        System.out.println(low);
    }
}

