typedef struct {
    ll time;   // next call time
    int id;
} WaitNode;

typedef struct {
    ll deadline; // current hangup time for active attempt
    int id;
} ReadyNode;

typedef struct {
    ll finish;
} BusyNode;

typedef struct {
    WaitNode *a;
    int n, cap;
} WaitHeap;

