} BusyHeap;

static void wait_push(WaitHeap *h, WaitNode v) {
    int i = h->n++;
    h->a[i] = v;
    while (i > 0) {
        int p = (i - 1) >> 1;
        if (h->a[p].time < h->a[i].time ||
           (h->a[p].time == h->a[i].time && h->a[p].id <= h->a[i].id)) break;
        WaitNode tmp = h->a[p]; h->a[p] = h->a[i]; h->a[i] = tmp;
        i = p;
    }
}
static WaitNode wait_pop(WaitHeap *h) {
    WaitNode ret = h->a[0];
    h->a[0] = h->a[--h->n];
    int i = 0;
    while (1) {
        int l = i * 2 + 1, r = l + 1, m = i;
        if (l < h->n && (h->a[l].time < h->a[m].time ||
            (h->a[l].time == h->a[m].time && h->a[l].id < h->a[m].id))) m = l;
        if (r < h->n && (h->a[r].time < h->a[m].time ||
            (h->a[r].time == h->a[m].time && h->a[r].id < h->a[m].id))) m = r;
        if (m == i) break;
        WaitNode tmp = h->a[m]; h->a[m] = h->a[i]; h->a[i] = tmp;
        i = m;
    }
    return ret;
}
static WaitNode wait_top(WaitHeap *h) { return h->a[0]; }

