                    progressed = 1;
                    continue;
                } else {
                    free(done); free(waith.a); free(readyh.a); free(busyh.a);
                    return 0;
                }
            }
            done[id] = 1;
            completed++;
            free_ops--;
            busy_push(&busyh, (BusyNode){cur + c[id].s});
            progressed = 1;
        }
        if (completed == n) break;
        if (progressed) continue;

        ll next_time = -1;
        if (busyh.n > 0) next_time = busy_top(&busyh).finish;
        if (waith.n > 0) {
            ll t2 = wait_top(&waith).time;
            if (next_time == -1 || t2 < next_time) next_time = t2;
        }
        if (readyh.n > 0 && free_ops > 0) {
            next_time = cur;
        }
        if (next_time == -1) {
            free(done); free(waith.a); free(readyh.a); free(busyh.a);
            return 0;
        }
        if (next_time < cur) next_time = cur;
        if (next_time == cur && !(readyh.n > 0 && free_ops > 0)) {
            free(done); free(waith.a); free(readyh.a); free(busyh.a);
            return 0;
        }
        cur = next_time;
        if (cur > T) {
            free(done); free(waith.a); free(readyh.a); free(busyh.a);
            return 0;
        }
    }

    free(done);
    free(waith.a);
    free(readyh.a);
    free(busyh.a);
    return 1;
}

